import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2023_energy.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

# Prepare adjacency dictionary
adjacency = {}
for borough in df['borough'].unique():
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adjacency[borough] = neighbors

# Implement ITERATIVE-R method
def iterative_r_outlier_detection(data, adjacency_dict, max_iter=10, threshold=2.5):
    # Initial setup
    values = data.set_index('borough')['Energy_value'].to_dict()
    residuals = values.copy()
    outliers = set()

    for _ in range(max_iter):
        # Calculate neighborhood averages excluding current outliers
        neighborhood_avgs = {}
        for borough in values:
            neighbors = [n for n in adjacency_dict.get(borough, []) if n not in outliers]
            if neighbors:
                neighborhood_avgs[borough] = np.mean([values[n] for n in neighbors])
            else:
                neighborhood_avgs[borough] = np.nan

        # Fit global regression (borough value ~ neighborhood average)
        valid = ~pd.Series(neighborhood_avgs).isna()
        X = np.array(list(neighborhood_avgs.values()))[valid]
        y = np.array(list(values.values()))[valid]

        if len(X) < 2:
            break

        # Simple linear regression
        X = X.reshape(-1, 1)
        coeff = np.linalg.lstsq(np.hstack([np.ones((len(X), 1)), X]), y, rcond=None)[0]
        predicted = coeff[0] + coeff[1] * X.flatten()

        # Calculate residuals
        residuals = {}
        for borough in values:
            if borough in neighborhood_avgs and not np.isnan(neighborhood_avgs[borough]):
                pred = coeff[0] + coeff[1] * neighborhood_avgs[borough]
                residuals[borough] = values[borough] - pred
            else:
                residuals[borough] = np.nan

        # Standardize residuals
        valid_residuals = [r for r in residuals.values() if not np.isnan(r)]
        if len(valid_residuals) < 2:
            break

        mean_res = np.mean(valid_residuals)
        std_res = np.std(valid_residuals)

        # Find most extreme residual
        z_scores = {b: (r - mean_res)/std_res for b, r in residuals.items() if not np.isnan(r)}
        if not z_scores:
            break

        max_borough = max(z_scores.keys(), key=lambda k: abs(z_scores[k]))
        max_z = z_scores[max_borough]

        if abs(max_z) > threshold:
            outliers.add(max_borough)
        else:
            break

    # Final evaluation for City of London
    city_of_london_z = z_scores.get('City of London', 0)

    if abs(city_of_london_z) > threshold:
        if city_of_london_z > 0:
            return f"FINAL ANSWER: OUTLIER - HIGH (z = {city_of_london_z})"
        else:
            return f"FINAL ANSWER: OUTLIER - LOW (z = {city_of_london_z})"
    else:
        return f"FINAL ANSWER: NOT AN OUTLIER (z = {city_of_london_z})"

# Run analysis and print result
result = iterative_r_outlier_detection(df, adjacency)
print(result)
